}

/** Makes one issue's entry match the rule. Its comments are untouched while it stays visible. */
export async function syncIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue && (await isIssueVisible(orgId, issue))) {
    await indexIssue(orgId, issue);
    return;
  }
  await searchRepo.deleteIssueSearchDocuments(orgId, issueId);
}

/** Makes one comment's entry match the rule. */
export async function syncComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<void> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment && (await isCommentVisible(orgId, comment))) {
    await indexComment(orgId, comment);
    return;
  }
  await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
}

/** Makes a project's own entry match the rule. Archiving a project drops everything under it. */
export async function syncProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project && isLive(project)) {
    await indexProject(orgId, project);
