/**
 * Restore: clears the project's subtree and walks it again. Only live issues
 * and live comments come back, so anything archived stays hidden.
 */
export async function syncProjectTree(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<IndexTally> {
  await searchRepo.deleteProjectSearchDocuments(orgId, projectId);

  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project || !isLive(project)) return { processed: 0, failed: 0 };

  return indexProjectTree(orgId, project);
}

