 * Upserts a live project together with its live issues and their live
 * comments. This one walk backs both the workspace rebuild and a project
 * restore, so the two cannot disagree about what is visible.
 */
export async function indexProjectTree(
  orgId: OrgId,
  project: Project,
): Promise<IndexTally> {
  const tally: IndexTally = { processed: 0, failed: 0 };

  await attempt(tally, "project", project.id, () =>
    indexProject(orgId, project),
  );

  const issues = eachPage((cursor) =>
    issueRepo.listIssues({
      orgId,
      projectId: project.id,
      includeArchived: false,
      limit: PAGE_SIZE,
      cursor,
    }),
  );

  for await (const issue of issues) {
    await attempt(tally, "issue", issue.id, () => indexIssue(orgId, issue));

    const comments = eachPage((cursor) =>
      commentRepo.listComments({
        orgId,
        issueId: issue.id,
        includeArchived: false,
        limit: PAGE_SIZE,
        cursor,
      }),
    );

    for await (const comment of comments) {
      await attempt(tally, "comment", comment.id, () =>
        indexComment(orgId, comment),
      );
    }
  }

  return tally;
}

/**
 * Rebuilds one workspace's index from its live content and drops the rest.
 * Every live project is walked through every page, so workspace size does not
 * matter. Only this org's entries are written or removed.
 */
export async function rebuildWorkspaceIndex(orgId: OrgId): Promise<IndexTally> {
  // Entries written before this instant and not revisited by the walk are stale.
  const passStartedAt: IsoTimestamp = toIsoTimestamp(new Date());
  const tally: IndexTally = { processed: 0, failed: 0 };

  const projects = eachPage((cursor) =>
    projectRepo.listProjects({
      orgId,
      limit: PAGE_SIZE,
      cursor,
      includeArchived: false,
    }),
  );

  for await (const project of projects) {
    const part = await indexProjectTree(orgId, project);
    tally.processed += part.processed;
    tally.failed += part.failed;
  }

  await searchRepo.deleteSearchDocumentsIndexedBefore(orgId, passStartedAt);
  return tally;
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so the index follows the stored state and
 * never the order in which events arrived.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", (payload) =>
      syncIssue(payload.orgId, payload.issueId),
    ),
    subscribe("issue.updated", (payload) =>
      syncIssue(payload.orgId, payload.issueId),
    ),
    subscribe("issue.archived", (payload) =>
      syncIssue(payload.orgId, payload.issueId),
    ),
    subscribe("comment.created", (payload) =>
      syncComment(payload.orgId, payload.commentId),
    ),
    subscribe("comment.updated", (payload) =>
      syncComment(payload.orgId, payload.commentId),
    ),
    subscribe("comment.deleted", (payload) =>
      syncComment(payload.orgId, payload.commentId),
    ),
    subscribe("project.created", (payload) =>
      syncProject(payload.orgId, payload.projectId),
    ),
    subscribe("project.updated", (payload) =>
      syncProject(payload.orgId, payload.projectId),
    ),
    subscribe("project.archived", (payload) =>
      syncProject(payload.orgId, payload.projectId),
    ),
    subscribe("project.restored", (payload) =>
      syncProjectTree(payload.orgId, payload.projectId).then(() => undefined),
    ),
    subscribe("search.reindex_requested", async (payload) => {
      if (payload.subjectKind !== "issue") return;
      await syncIssue(payload.orgId, payload.subjectId as IssueId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/** Live issue in a live project. */
async function isIssueVisible(orgId: OrgId, issue: Issue): Promise<boolean> {
  if (!isLive(issue)) return false;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project !== null && isLive(project);
}

/** Live comment on a visible issue. */
async function isCommentVisible(
  orgId: OrgId,
  comment: Comment,
): Promise<boolean> {
  if (!isLive(comment)) return false;
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  return issue !== null && (await isIssueVisible(orgId, issue));
}

/** Walks every page of a cursor-paged listing, one row at a time. */
async function* eachPage<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
): AsyncGenerator<T> {
  let cursor: string | null = null;
  do {
    const page = await fetchPage(cursor);
    yield* page.items;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/** Runs one index write, counting it; a failure is logged and the walk carries on. */
async function attempt(
  tally: IndexTally,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  write: () => Promise<void>,
): Promise<void> {
  try {
    await write();
    tally.processed += 1;
  } catch (error) {
    tally.failed += 1;
    logger.error("failed to index search entry", {
      subjectKind,
      subjectId,
      reason: error instanceof Error ? error.message : String(error),
    });
  }
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

function snippetAround(content: string, query: string): string {
  const at = content.toLowerCase().indexOf(query.toLowerCase());
  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);

  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
    end < content.length ? "…" : ""
  }`;
}

