/**
 * Query-time search plus the write-time index maintenance driven by domain events.
 *
 * Visibility rule: a project is indexed while it is live; an issue while it and
 * its project are live; a comment while it, its issue and that issue's project
 * are live. Every write path below re-reads the row and applies that rule, so
 * the index holds exactly the visible entries.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { isLive } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { toIsoTimestamp } from "@/types/common";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IssueId,
  IsoTimestamp,
  OrgId,
  Page,
  ProjectId,
} from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Outcome of an index walk, in the shape job results report. */
export type IndexTally = { processed: number; failed: number };

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/** Rows read per page while walking live content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-service");

/**
 * Runs a query against the denormalised index. Field-scoped syntax
 * (`status:done`) is an `advanced_search` feature, so a query containing a
 * colon is rejected for plans that do not include it rather than silently
 * being treated as literal text.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.q.includes(":") && !advanced) {
    throw new Error("Field-scoped search is not included in this plan");
  }

  const page = await searchRepo.searchDocuments(input);

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, input.q),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

/*
 * The `index*` writers store whatever they are given. Deciding whether a row is
 * visible is the caller's job: the `sync*` functions and the tree walk below.
 */

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/** Makes one issue's entry match the rule. Its comments are untouched while it stays visible. */
export async function syncIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue && (await isIssueVisible(orgId, issue))) {
    await indexIssue(orgId, issue);
    return;
  }
  await searchRepo.deleteIssueSearchDocuments(orgId, issueId);
}

/** Makes one comment's entry match the rule. */
export async function syncComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<void> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment && (await isCommentVisible(orgId, comment))) {
    await indexComment(orgId, comment);
    return;
  }
  await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
}

/** Makes a project's own entry match the rule. Archiving a project drops everything under it. */
export async function syncProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project && isLive(project)) {
    await indexProject(orgId, project);
    return;
  }
  await searchRepo.deleteProjectSearchDocuments(orgId, projectId);
}

/**
 * Restore: clears the project's subtree and walks it again. Only live issues
 * and live comments come back, so anything archived stays hidden.
 */
export async function syncProjectTree(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<IndexTally> {
  await searchRepo.deleteProjectSearchDocuments(orgId, projectId);

  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project || !isLive(project)) return { processed: 0, failed: 0 };

  return indexProjectTree(orgId, project);
}

/**
 * Upserts a live project together with its live issues and their live
 * comments. This one walk backs both the workspace rebuild and a project
 * restore, so the two cannot disagree about what is visible.
 */
export async function indexProjectTree(
  orgId: OrgId,
  project: Project,
): Promise<IndexTally> {
  const tally: IndexTally = { processed: 0, failed: 0 };

  await attempt(tally, "project", project.id, () =>
    indexProject(orgId, project),
  );

  const issues = eachPage((cursor) =>
    issueRepo.listIssues({
      orgId,
      projectId: project.id,
      includeArchived: false,
      limit: PAGE_SIZE,
      cursor,
    }),
  );

  for await (const issue of issues) {
    await attempt(tally, "issue", issue.id, () => indexIssue(orgId, issue));

    const comments = eachPage((cursor) =>
      commentRepo.listComments({
        orgId,
        issueId: issue.id,
        includeArchived: false,
        limit: PAGE_SIZE,
        cursor,
      }),
    );

    for await (const comment of comments) {
      await attempt(tally, "comment", comment.id, () =>
        indexComment(orgId, comment),
      );
    }
  }

  return tally;
}

/**
 * Rebuilds one workspace's index from its live content and drops the rest.
 * Every live project is walked through every page, so workspace size does not
 * matter. Only this org's entries are written or removed.
 */
export async function rebuildWorkspaceIndex(orgId: OrgId): Promise<IndexTally> {
  // Entries written before this instant and not revisited by the walk are stale.
  const passStartedAt: IsoTimestamp = toIsoTimestamp(new Date());
  const tally: IndexTally = { processed: 0, failed: 0 };

  const projects = eachPage((cursor) =>
    projectRepo.listProjects({
      orgId,
      limit: PAGE_SIZE,
      cursor,
      includeArchived: false,
    }),
  );

  for await (const project of projects) {
    const part = await indexProjectTree(orgId, project);
    tally.processed += part.processed;
    tally.failed += part.failed;
  }

  await searchRepo.deleteSearchDocumentsIndexedBefore(orgId, passStartedAt);
  return tally;
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so the index follows the stored state and
 * never the order in which events arrived.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", (payload) =>
      syncIssue(payload.orgId, payload.issueId),
    ),
    subscribe("issue.updated", (payload) =>
      syncIssue(payload.orgId, payload.issueId),
    ),
    subscribe("issue.archived", (payload) =>
      syncIssue(payload.orgId, payload.issueId),
    ),
    subscribe("comment.created", (payload) =>
      syncComment(payload.orgId, payload.commentId),
    ),
    subscribe("comment.updated", (payload) =>
      syncComment(payload.orgId, payload.commentId),
    ),
    subscribe("comment.deleted", (payload) =>
      syncComment(payload.orgId, payload.commentId),
    ),
    subscribe("project.created", (payload) =>
      syncProject(payload.orgId, payload.projectId),
    ),
    subscribe("project.updated", (payload) =>
      syncProject(payload.orgId, payload.projectId),
    ),
    subscribe("project.archived", (payload) =>
      syncProject(payload.orgId, payload.projectId),
    ),
    subscribe("project.restored", (payload) =>
      syncProjectTree(payload.orgId, payload.projectId).then(() => undefined),
    ),
    subscribe("search.reindex_requested", async (payload) => {
      if (payload.subjectKind !== "issue") return;
      await syncIssue(payload.orgId, payload.subjectId as IssueId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

