/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): rebuildWorkspaceIndex
 */
import { rebuildWorkspaceIndex } from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/**
 * Re-derives one tenant's index from its live content and drops everything
 * the visibility rule hides. Scoped to a single org on purpose: a full-fleet
 * reindex is a sequence of these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const tally = await rebuildWorkspaceIndex(orgId);
    result.processed += tally.processed;
    result.failed += tally.failed;
  });
}

