import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

async function count(tenant: Tenant, q: string, kind: "issue" | "comment" | "project") {
  const page = await searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds: [kind],
    limit: 100,
    cursor: null,
  });
  return page.total;
}

describe("scratch: visibility rule", () => {
  it("archived issue hides the issue and its comments", async () => {
    const t = await createTenant("scratcha", "growth");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "AAtitle" }),
    );
    await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue.id, body: "AAcomment", parentId: null, mentionedUserIds: [],
    });
    expect(await count(t, "AAtitle", "issue")).toBe(1);
    expect(await count(t, "AAcomment", "comment")).toBe(1);

    await issueService.archiveIssue(t.actors.admin, t.org.id, issue.id);
    expect(await count(t, "AAtitle", "issue")).toBe(0);
    expect(await count(t, "AAcomment", "comment")).toBe(0);
  });

  it("archive project (issues kept) hides everything; later comments/edits stay hidden; restore brings live content back", async () => {
    const t = await createTenant("scratchb", "growth");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "BPone" }),
    );
    await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue.id, body: "BPcomment1", parentId: null, mentionedUserIds: [],
    });
    const projectName = t.project.name;
    expect(await count(t, projectName, "project")).toBe(1);

    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id, projectId: t.project.id, archiveIssues: false,
    });
    expect(await count(t, projectName, "project")).toBe(0);
    expect(await count(t, "BPone", "issue")).toBe(0);
    expect(await count(t, "BPcomment1", "comment")).toBe(0);

    await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue.id, body: "BPcomment2", parentId: null, mentionedUserIds: [],
    });
    await issueService.updateIssue(t.actors.member, {
      orgId: t.org.id, issueId: issue.id, title: "BPoneEdited",
    });
    expect(await count(t, "BPcomment2", "comment")).toBe(0);
    expect(await count(t, "BPoneEdited", "issue")).toBe(0);

    await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect(await count(t, projectName, "project")).toBe(1);
    expect(await count(t, "BPoneEdited", "issue")).toBe(1);
    expect(await count(t, "BPcomment1", "comment")).toBe(1);
    expect(await count(t, "BPcomment2", "comment")).toBe(1);
  });

  it("archive project with cascade, plus an issue archived earlier: nothing issue-level returns on restore", async () => {
    const t = await createTenant("scratchc", "growth");
    const pre = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "CYpre" }),
    );
    await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: pre.id, body: "CYprecomment", parentId: null, mentionedUserIds: [],
    });
    await issueService.archiveIssue(t.actors.admin, t.org.id, pre.id);

    const live = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "CXlive" }),
    );
    await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: live.id, body: "CXcomment", parentId: null, mentionedUserIds: [],
    });

    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id, projectId: t.project.id, archiveIssues: true,
    });
    await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);

    expect(await count(t, t.project.name, "project")).toBe(1);
    expect(await count(t, "CYpre", "issue")).toBe(0);
    expect(await count(t, "CYprecomment", "comment")).toBe(0);
    expect(await count(t, "CXlive", "issue")).toBe(0);
    expect(await count(t, "CXcomment", "comment")).toBe(0);
  });

  it("comment deletion and issue-level archive remove comments", async () => {
    const t = await createTenant("scratchd", "growth");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "DDissue" }),
    );
    const c = await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue.id, body: "DDdeleteme", parentId: null, mentionedUserIds: [],
    });
    await commentService.deleteComment(t.actors.member, { orgId: t.org.id, commentId: c.id });
    expect(await count(t, "DDdeleteme", "comment")).toBe(0);
  });
});

describe("scratch: rebuild", () => {
  it("rebuild on a large workspace keeps exactly the visible entries and drops stale ones, leaving other workspaces alone", async () => {
    const other = await createTenant("scratche-other", "growth");
    await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "OTHERmarker" }),
    );
    const otherBefore = await searchRepo.countIndexed(other.org.id);

    const t = await createTenant("scratche", "growth");
    const issues: string[] = [];
    for (let i = 0; i < 120; i += 1) {
      const issue = await issueService.createIssue(
        t.actors.member,
        issueInput(t.org.id, t.project.id, { title: `BULK issue ${i}` }),
      );
      issues.push(issue.id);
    }
    const hub = issues[0]!;
    for (let i = 0; i < 105; i += 1) {
      await commentService.createComment(t.actors.member, {
        orgId: t.org.id, issueId: hub, body: `BULKcomment ${i}`, parentId: null, mentionedUserIds: [],
      });
    }

    // Stale state: an archived issue and a deleted comment that the index still holds.
    const stale = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "STALEissue" }),
    );
    await issueRepo.archiveIssue(t.org.id, stale.id);
    await searchRepo.upsertSearchDocument(t.org.id, "issue", stale.id, "STALEissue\n", t.project.id);
    const deleted = await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: hub, body: "STALEcomment", parentId: null, mentionedUserIds: [],
    });
    await commentRepo.archiveComment(t.org.id, deleted.id);
    await searchRepo.upsertSearchDocument(t.org.id, "comment", deleted.id, "STALEcomment", null);
    // Archived project content that was indexed before the archive.
    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id, projectId: t.project.id, archiveIssues: false,
    });
    await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    await searchRepo.upsertSearchDocument(t.org.id, "project", t.project.id, "GHOSTproject", t.project.id);

    const result = await runSearchReindexJob(t.org.id);
    expect(result.failed).toBe(0);

    // 1 project + 121 live issues (120 bulk + the "stale" one is archived -> 120) + 105 live comments
    expect(await searchRepo.countIndexed(t.org.id)).toBe(1 + 120 + 105);
    expect(await count(t, "STALEissue", "issue")).toBe(0);
    expect(await count(t, "STALEcomment", "comment")).toBe(0);
    expect(await count(t, "GHOSTproject", "project")).toBe(0);
    expect(await count(t, "BULKcomment 104", "comment")).toBe(1);
    expect(await count(t, "BULK issue 119", "issue")).toBe(1);

    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherBefore);
    expect(await count(other, "OTHERmarker", "issue")).toBe(1);
  });
});

